def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    ones = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 1]
    sixes = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 6]

    # Join diagonal pairs of 1s.
    diagonal_lines = set()
    for i, (r1, c1) in enumerate(ones):
        for r2, c2 in ones[i + 1:]:
            if r1 != r2 and abs(r2 - r1) == abs(c2 - c1):
                slope = 1 if (r2-r1) * (c2-c1) > 0 else -1
                key = (slope, c1-r1 if slope == 1 else c1+r1)
                diagonal_lines.add(key)
                dr = 1 if r2 > r1 else -1
                dc = 1 if c2 > c1 else -1
                r, c = r1, c1
                while True:
                    if grid[r][c] != 6:
                        out[r][c] = 1
                    if (r, c) == (r2, c2):
                        break
                    r += dr
                    c += dc

    # A 6 on a joined 1 diagonal creates a full line in the other diagonal direction.
    for r0, c0 in sixes:
        for slope, intercept in diagonal_lines:
            on_line = (c0-r0 == intercept) if slope == 1 else (c0+r0 == intercept)
            if on_line:
                for r in range(h):
                    c = c0 - (r-r0) if slope == 1 else c0 + (r-r0)
                    if 0 <= c < w:
                        out[r][c] = 6

    return out
